        for (LeagueRegionBounds LocalCurrentRegion : config.RegionData.RegionData)
        {
            LocalCurrentRegion.RegionPoints.forEach((key, value) ->
            {
                SetMarkerActivation(value, false);
            });
        }

        RefreshRegionBounds();
        overlayManager.add(regionBoundOverlay);
    }

